var p=$json.paket||$json;
var burchak=(p.burchaklar&&p.burchaklar.thumbnail&&p.burchaklar.thumbnail[0])||"Thumbnail";
var tpid=p.talking_photo_id||"08617ecb814d40be876db3b1c7b83da0";
var yt_sar=$json.yt_sarlavha||p.sarlavha||burchak;
var faktlar=p.faktlar||[];
// Validate raqam in faktlar
var fr=[];for(var fi=0;fi<faktlar.length;fi++){var m=String(faktlar[fi].matn||"").match(new RegExp("[0-9]+","g"))||[];for(var j=0;j<m.length;j++)fr.push(m[j]);}
// Check thumbnail raqam
var pm=burchak.match(new RegExp("%([0-9]+)","g"))||[];var xatolar=[];
for(var pi=0;pi<pm.length;pi++){var n=pm[pi].replace("%","");var f=false;for(var fk=0;fk<fr.length;fk++){if(fr[fk].indexOf(n)>=0){f=true;break;}}if(!f)xatolar.push("Ixtiro raqam: "+pm[pi]);}
return{json:{job_id:p.job_id||"UNKNOWN",burchak:burchak,yt_sarlavha:yt_sar,faktlar:faktlar,talking_photo_id:tpid,xatolar:xatolar,holat:xatolar.length===0?"PASS":"FAIL"}};

